mapper.sql:
WHERE version_id = #{versionId}
AND bin_prefix LIKE CONCAT(#{filter.binPrefix}, '%')
AND card_brand = #{filter.cardBrand,javaType=com.paytech.card.api.enums.CardBrand,typeHandler=com.paytech.foundation.mybatis.typehandler.CodeEnumTypeHandler,jdbcType=VARCHAR}
AND funding_type = #{filter.fundingType,javaType=com.paytech.card.api.enums.CardFundingType,typeHandler=com.paytech.foundation.mybatis.typehandler.CodeEnumTypeHandler,jdbcType=VARCHAR}
AND issuer_country = #{filter.issuerCountry}

mapper.select:
SELECT v.version_no, v.status AS version_status, r.bin_prefix, r.prefix_length, r.card_brand, r.funding_type, r.card_level, r.card_product, r.issuer_country, r.issuer_region, r.issuer_name FROM t_card_bin_library_version v LEFT JOIN t_card_bin_range r ON r.version_id = v.version_id AND r.bin_prefix IN #{prefix}
v.version_no = #{versionNo} v.active_slot = 1
ORDER BY r.prefix_length DESC LIMIT 1
